python3 - <<'PYEOF'
p = '/private/tmp/claude-501/-Users-guillaumeloulier-PhpstormProjects-oss-elephc--claude-worktrees-streams-csv-signature/c8dbe38f-1f79-484f-9b83-62bacab9ca56/scratchpad/select_mem_test.rs'
s = open(p).read()
start = s.index('function probe(')
end = s.index('fclose($m);\n"#,') + len('fclose($m);\n')

new = '''// Each label is built and printed only once the call has resolved, so where the warnings go
// cannot interleave with stdout — the diagnostic stream is asserted separately below.
function probe(string $label, $s): string {
    $r = [$s];
    $w = null;
    $e = null;
    try {
        return $label . "=" . var_export(stream_select($r, $w, $e, 0), true);
    } catch (ValueError $ex) {
        return $label . "=VE:" . $ex->getMessage();
    }
}
$out = [];
$out[] = probe("file", fopen("selmem.txt", "r"));
$out[] = probe("memory", fopen("php://memory", "w+"));
$out[] = probe("temp", fopen("php://temp", "w+"));
$out[] = probe("data", fopen("data://text/plain,hi", "r"));
$f = fopen("selmem.txt", "r");
$m = fopen("php://memory", "w+");
$r = [$f, $m];
$w = null;
$e = null;
$n = stream_select($r, $w, $e, 0);
$out[] = "mixed=" . $n . "|" . count($r);
fclose($f);
fclose($m);
echo implode("\\n", $out), "\\n";
'''
s = s[:start] + new + s[end:]
open(p, 'w').write(s)
print("probe restructured")
